import axios from 'axios';
import assert from 'node:assert/strict';
const key = process.env.GOOGLE_FONTS_API_KEY;
assert.ok(key, 'World-issued GOOGLE_FONTS_API_KEY is required');
const res = await axios.get(`https://www.googleapis.com/webfonts/v1/webfonts?sort=popularity&key=${key}`, { responseType: 'json', maxRedirects: 0 });
assert.equal(res.data.kind, 'webfonts#webfontList');
const item = res.data.items.find(f => f.family === 'Antic');
assert.ok(item); assert.ok(item.variants.includes('regular')); assert.ok(item.subsets.includes('latin'));
const agents = {"0": "Mozilla/5.0 (compatible; MSIE 8.0; Windows NT 6.1; Trident/4.0)", "1": "Mozilla/5.0 (Windows NT 6.1; WOW64; rv:27.0) Gecko/20100101 Firefox/27.0", "2": "Mozilla/5.0 (Windows NT 6.3; rv:39.0) Gecko/20100101 Firefox/39.0", "3": "Mozilla/4.0 (iPad; CPU OS 4_0_1 like Mac OS X) AppleWebKit/534.46 (KHTML, like Gecko) Version/4.1 Mobile/9A405 Safari/7534.48.3", "4": "Mozilla/5.0 (Unknown; Linux x86_64) AppleWebKit/538.1 (KHTML, like Gecko) Safari/538.1 Daum/4.1"};
for (const agent of Object.values(agents)) {
 const css = await axios.get('http://fonts.googleapis.com/css?family='+encodeURIComponent(item.family+':regular')+'&subset=latin', { responseType: 'text', maxRedirects: 0, headers: { Accept: 'text/css,*/*;q=0.1', 'User-Agent': agent } });
 assert.match(css.data, /@font-face/);
 const url = css.data.match(/url\((https?:\/\/[^)]+)\)/)?.[1]; assert.ok(url);
 const file = await axios.get(url.replace('http://','https://'), { responseType: 'arraybuffer', maxRedirects: 0 });
 assert.ok(file.data.length > 0); assert.ok(file.headers['content-type']);
}
console.log('Read retained Google Fonts catalog, CSS and bytes through unchanged axios calls');
